#[derive(Debug)]
struct DoctorMutationLockGuard {
    file: std::fs::File,
}

impl Drop for DoctorMutationLockGuard {
    fn drop(&mut self) {
        let _ = fs2::FileExt::unlock(&self.file);
    }
}

#[derive(Debug, Clone)]
enum DoctorMutationLockObservation {
    Absent {
        path: PathBuf,
    },
    Available {
        path: PathBuf,
        metadata: BTreeMap<String, String>,
    },
    Active {
        path: PathBuf,
        metadata: BTreeMap<String, String>,
    },
    Acquired {
        path: PathBuf,
        metadata: BTreeMap<String, String>,
    },
    Unavailable {
        path: PathBuf,
        reason: String,
    },
}

impl DoctorMutationLockObservation {
    fn path(&self) -> &Path {
        match self {
            Self::Absent { path }
            | Self::Available { path, .. }
            | Self::Active { path, .. }
            | Self::Acquired { path, .. }
            | Self::Unavailable { path, .. } => path,
        }
    }

    fn blocks_mutation(&self) -> bool {
        matches!(self, Self::Active { .. } | Self::Unavailable { .. })
    }
}

const DOCTOR_STORAGE_MIN_FREE_BYTES: u64 = 1024 * 1024 * 1024;
const CASS_TEST_DOCTOR_STORAGE_AVAILABLE_BYTES: &str = "CASS_TEST_DOCTOR_STORAGE_AVAILABLE_BYTES";
const CASS_RAW_MIRROR_SIZE_WARN_THRESHOLD_BYTES: &str = "CASS_RAW_MIRROR_SIZE_WARN_THRESHOLD_BYTES";
const DOCTOR_RAW_MIRROR_SIZE_WARN_THRESHOLD_BYTES_DEFAULT: u64 = 100 * 1_000_000_000;
const DOCTOR_RAW_MIRROR_SOURCE_AMPLIFICATION_WARN_RATIO_MILLI_DEFAULT: u64 = 4_000;
const DOCTOR_RAW_MIRROR_SOURCE_AMPLIFICATION_WARN_EXCESS_BYTES_DEFAULT: u64 = 256 * 1024 * 1024;
const DOCTOR_RAW_MIRROR_MANIFEST_MAX_BYTES: u64 = 16 * 1024 * 1024;
const DOCTOR_RAW_MIRROR_AMPLIFICATION_MANIFEST_MAX_BYTES: u64 = 1024 * 1024;
const DOCTOR_RAW_MIRROR_BOUNDED_AMPLIFICATION_MANIFEST_LIMIT: usize = 4_096;
const DOCTOR_RAW_MIRROR_BOUNDED_AMPLIFICATION_BYTE_LIMIT: u64 = 64 * 1024 * 1024;
const CASS_TEST_DOCTOR_CANDIDATE_PROMOTION_FAILPOINT: &str =
    "CASS_TEST_DOCTOR_CANDIDATE_PROMOTION_FAILPOINT";
const CASS_TEST_DOCTOR_RENAME_FAILURE: &str = "CASS_TEST_DOCTOR_RENAME_FAILURE";
const DOCTOR_SLOW_OPERATION_DEFAULT_THRESHOLD_MS: u64 = 500;
/// World-class-doctor pass-4: lowered from 1 hour to 5 minutes per the
/// safety-envelope hardening pass, so a stale lock stops blocking repairs
/// after 5 minutes instead of an hour. While the holder is live, a second
/// `cass doctor --fix` reports repair-blocked (exit 7 `index-busy` when failed
/// checks remain).
///
/// The stale-detection threshold is the lock-metadata `started_at_ms` /
/// `updated_at_ms` age in ms.
///
/// **Pass-11 fix:** an earlier docstring claimed
/// `CASS_DOCTOR_LOCK_HEARTBEAT_STALE_AFTER_MS` could be set as an env var
/// override. That env var was never wired in code — it was false advertising.
/// The capabilities surface previously echoed the same false claim; both have
/// been corrected. Future passes may wire an env override; for now this is a
/// compile-time constant.
const DOCTOR_LOCK_HEARTBEAT_STALE_AFTER_MS: u64 = 5 * 60 * 1000;

