fn doctor_source_authority_policy(
    authority: DoctorSourceAuthorityKind,
) -> &'static DoctorSourceAuthorityPolicy {
    DOCTOR_SOURCE_AUTHORITY_POLICY_TABLE
        .iter()
        .find(|policy| policy.authority == authority)
        .expect("doctor source authority policy table must cover every authority")
}

fn doctor_source_authority_matrix_report() -> Vec<DoctorSourceAuthorityMatrixEntry> {
    DOCTOR_SOURCE_AUTHORITY_POLICY_TABLE
        .iter()
        .map(|policy| DoctorSourceAuthorityMatrixEntry {
            authority: policy.authority,
            repairs: policy.repairs.to_vec(),
            required_evidence: policy.required_evidence.to_vec(),
            refuses_when: policy.refuses_when.to_vec(),
            decision_when_valid: policy.decision_when_valid,
            notes: policy.notes,
        })
        .collect()
}

fn doctor_source_inventory_stable_id(
    provider: &str,
    source_id: &str,
    origin_kind: Option<&str>,
    origin_host: Option<&str>,
    source_path: Option<&str>,
) -> String {
    doctor_canonical_blake3(
        "doctor-source-inventory-v1",
        serde_json::json!({
            "provider": provider,
            "source_id": source_id,
            "origin_kind": origin_kind,
            "origin_host": origin_host,
            "source_path": source_path,
        }),
    )
}

fn doctor_table_columns(conn: &crate::franken_sync::Connection, table: &str) -> HashSet<String> {
    if !table.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return HashSet::new();
    }
    conn.query_map_collect(
        &format!("PRAGMA table_info({table})"),
        &[],
        |row: &crate::franken_sync::Row| row.get_typed::<String>(1),
    )
    .unwrap_or_default()
    .into_iter()
    .collect()
}

fn query_doctor_source_inventory_db_rows(
    conn: &crate::franken_sync::Connection,
) -> std::result::Result<Vec<DoctorSourceInventoryDbRow>, crate::franken_sync::FrankenError> {
    use crate::franken_sync::compat::ConnectionExt as _;

    let conversation_columns = doctor_table_columns(conn, "conversations");
    if conversation_columns.is_empty() {
        return Ok(Vec::new());
    }
    let agent_columns = doctor_table_columns(conn, "agents");
    let source_columns = doctor_table_columns(conn, "sources");

    let can_join_agents = conversation_columns.contains("agent_id")
        && agent_columns.contains("id")
        && agent_columns.contains("slug");
    let can_join_sources = conversation_columns.contains("source_id")
        && source_columns.contains("id")
        && source_columns.contains("kind");

    let provider_expr = if can_join_agents {
        "COALESCE(a.slug, 'unknown')"
    } else {
        "'unknown'"
    };
    let source_path_expr = if conversation_columns.contains("source_path") {
        "c.source_path"
    } else {
        "NULL"
    };
    let source_id_expr = if conversation_columns.contains("source_id") {
        "COALESCE(c.source_id, 'local')"
    } else {
        "'local'"
    };
    let origin_host_expr = if conversation_columns.contains("origin_host") {
        "c.origin_host"
    } else {
        "NULL"
    };
    let origin_kind_expr = if can_join_sources { "s.kind" } else { "NULL" };
    let agent_join = if can_join_agents {
        " LEFT JOIN agents a ON c.agent_id = a.id"
    } else {
        ""
    };
    let source_join = if can_join_sources {
        " LEFT JOIN sources s ON c.source_id = s.id"
    } else {
        ""
    };
    // Keep the database side of this inventory to a plain metadata scan.  The
    // report builder below already folds rows into deterministic BTreeMaps, so
    // asking the SQL engine to GROUP BY and ORDER BY the same dimensions only
    // duplicates work.  More importantly, FrankenSQLite currently materializes
    // that aggregate/sort pipeline; on a multi-million-message archive the
    // transient values can dwarf the conversations table and exhaust memory.
    // Emitting one unit row per conversation preserves the exact aggregation
    // semantics while keeping the SQL executor streaming and sorter-free.
    let sql = format!(
        "SELECT {provider_expr}, {source_path_expr}, {source_id_expr}, {origin_host_expr}, {origin_kind_expr}, 1 \
         FROM conversations c{agent_join}{source_join}"
    );

    conn.query_map_collect(&sql, &[], |row: &crate::franken_sync::Row| {
        let count: i64 = row.get_typed(5)?;
        Ok(DoctorSourceInventoryDbRow {
            provider: row.get_typed(0)?,
            source_path: row.get_typed(1)?,
            source_id: row.get_typed(2)?,
            origin_host: row.get_typed(3)?,
            origin_kind: row.get_typed(4)?,
            conversation_count: count.max(0) as usize,
        })
    })
}

fn build_doctor_source_inventory_report(
    data_dir: &Path,
    db_available: bool,
    db_query_error: Option<String>,
    db_rows: Vec<DoctorSourceInventoryDbRow>,
    detected_roots: Vec<(String, PathBuf)>,
) -> DoctorSourceInventoryReport {
    let mut provider_builders: BTreeMap<String, DoctorProviderInventoryBuilder> = BTreeMap::new();
    let mut source_builders: BTreeMap<String, DoctorSourceIdentityInventoryBuilder> =
        BTreeMap::new();
    let mut provider_counts = BTreeMap::new();
    let mut report = DoctorSourceInventoryReport {
        schema_version: 1,
        db_available,
        db_query_error,
        notes: vec![
            "missing_current_source_count means the original provider file is not visible now; indexed conversations remain in the cass archive database.".to_string(),
            "Remote rows are not checked against the local filesystem; use source_id and origin_host to identify the origin machine when known.".to_string(),
        ],
        ..DoctorSourceInventoryReport::default()
    };

    for (provider, root) in detected_roots {
        let provider = doctor_normalized_provider_slug(&provider);
        let root_path = root.display().to_string();
        let stable_source_id = doctor_source_inventory_stable_id(
            &provider,
            "detected-root",
            None,
            None,
            Some(&root_path),
        );
        let detected_root = DoctorDetectedProviderRoot {
            provider: provider.clone(),
            stable_source_id,
            redacted_path: doctor_redacted_path(&root_path, data_dir),
            exists: root.exists(),
            path: root_path,
        };
        report.detected_roots.push(detected_root.clone());
        provider_builders
            .entry(provider)
            .or_default()
            .detected_roots
            .push(detected_root);
    }

    for row in db_rows {
        let provider = doctor_normalized_provider_slug(&row.provider);
        let source_path = doctor_normalized_source_path(row.source_path.as_deref());
        let origin_host = normalized_provenance_origin_host(row.origin_host.as_deref());
        let source_id = normalized_provenance_source_id(
            row.source_id.as_str(),
            row.origin_kind.as_deref(),
            origin_host.as_deref(),
        );
        let origin_kind =
            normalized_provenance_origin_kind(source_id.as_str(), row.origin_kind.as_deref());
        let is_remote = origin_kind != crate::sources::provenance::LOCAL_SOURCE_ID;
        let local_path_missing = !is_remote
            && source_path
                .as_deref()
                .map(|path| !Path::new(path).exists())
                .unwrap_or(false);
        let unknown_mapping = provider == "unknown" || source_path.is_none();
        let count = row.conversation_count;

        report.total_indexed_conversations += count;
        *provider_counts.entry(provider.clone()).or_insert(0) += count;
        if is_remote {
            report.remote_source_count += count;
        } else {
            report.local_source_count += count;
        }
        if local_path_missing {
            report.missing_current_source_count += count;
        }
        if unknown_mapping {
            report.unknown_mapping_count += count;
        }

        let provider_builder = provider_builders.entry(provider.clone()).or_default();
        provider_builder.indexed_conversation_count += count;
        if is_remote {
            provider_builder.remote_source_count += count;
        } else {
            provider_builder.local_source_count += count;
        }
        if local_path_missing {
            provider_builder.missing_current_source_count += count;
        }
        if unknown_mapping {
            provider_builder.unknown_mapping_count += count;
        }

        let source_stable_id = doctor_source_inventory_stable_id(
            "source-identity",
            &source_id,
            Some(&origin_kind),
            origin_host.as_deref(),
            None,
        );
        let source_builder = source_builders.entry(source_stable_id).or_insert_with(|| {
            DoctorSourceIdentityInventoryBuilder {
                source_id: source_id.clone(),
                origin_kind: origin_kind.clone(),
                origin_host: origin_host.clone(),
                is_remote,
                ..DoctorSourceIdentityInventoryBuilder::default()
            }
        });
        source_builder.providers.insert(provider);
        source_builder.conversation_count += count;
        if local_path_missing {
            source_builder.missing_current_source_count += count;
        }
        if unknown_mapping {
            source_builder.unknown_mapping_count += count;
        }
    }

    report.provider_counts = provider_counts;
    report.detected_provider_root_count = report.detected_roots.len();

    report.providers = provider_builders
        .into_iter()
        .map(|(provider, builder)| {
            let stable_source_id =
                doctor_source_inventory_stable_id(&provider, "provider-rollup", None, None, None);
            let detected_root_count = builder.detected_roots.len();
            let mut notes = Vec::new();
            if builder.missing_current_source_count > 0 {
                notes.push(
                    "Some indexed local conversations no longer have a visible upstream provider file; this is a source coverage warning, not archive data loss."
                        .to_string(),
                );
            }
            if builder.unknown_mapping_count > 0 {
                notes.push(
                    "Some indexed conversations lack enough provider/path metadata for precise source mapping."
                        .to_string(),
                );
            }
            DoctorProviderSourceInventory {
                provider: provider.clone(),
                stable_source_id,
                indexed_conversation_count: builder.indexed_conversation_count,
                missing_current_source_count: builder.missing_current_source_count,
                unknown_mapping_count: builder.unknown_mapping_count,
                remote_source_count: builder.remote_source_count,
                local_source_count: builder.local_source_count,
                detected_root_count,
                detected_roots: builder.detected_roots,
                prune_risk: doctor_provider_prune_risk(&provider),
                notes,
            }
        })
        .collect();

    report.sources = source_builders
        .into_iter()
        .map(|(stable_source_id, builder)| {
            let mut providers: Vec<String> = builder.providers.into_iter().collect();
            providers.sort();
            DoctorSourceIdentityInventory {
                stable_source_id,
                source_id: builder.source_id,
                origin_kind: builder.origin_kind,
                origin_host: builder.origin_host,
                is_remote: builder.is_remote,
                providers,
                conversation_count: builder.conversation_count,
                missing_current_source_count: builder.missing_current_source_count,
                unknown_mapping_count: builder.unknown_mapping_count,
            }
        })
        .collect();

    report
}

fn collect_doctor_source_inventory(data_dir: &Path, db_path: &Path) -> DoctorSourceInventoryReport {
    let home = dirs::home_dir().unwrap_or_default();
    let config_dir = dirs::config_dir().unwrap_or_else(|| data_dir.to_path_buf());
    let detected_roots: Vec<_> = diagnostics_connector_paths(&home, &config_dir)
        .into_iter()
        .filter(|(_, path)| {
            let under = |base: &Path| !base.as_os_str().is_empty() && path.starts_with(base);
            under(&home) || under(&config_dir) || under(data_dir)
        })
        .collect();
    if !db_path.exists() {
        return build_doctor_source_inventory_report(
            data_dir,
            false,
            None,
            Vec::new(),
            detected_roots,
        );
    }

    let query_result = open_franken_cli_read_db(
        db_path.to_path_buf(),
        "doctor source inventory",
        Duration::from_secs(1),
    )
    .and_then(|conn| {
        let query_result = query_doctor_source_inventory_db_rows(&conn).map_err(|e| CliError {
            code: 9,
            kind: CliErrorKind::DbQuery.kind_str(),
            message: format!("Failed to query doctor source inventory: {e}"),
            hint: None,
            retryable: false,
        });
        let close_result = close_franken_cli_read_db(conn, db_path, "doctor source inventory");
        match (query_result, close_result) {
            (Ok(rows), Ok(())) => Ok(rows),
            (Err(err), _) | (_, Err(err)) => Err(err),
        }
    });

    match query_result {
        Ok(rows) => {
            build_doctor_source_inventory_report(data_dir, true, None, rows, detected_roots)
        }
        // The DB file exists but could not be read (unopenable/malformed, or a
        // read timeout). `db_available` must reflect *readability*, not mere
        // existence: reporting `true` here laundered a failed open into an
        // "available archive" whose default 0-row count was then promoted into
        // `archive-db-opened` evidence and selected as repair authority over a
        // checksum-verified raw mirror (#374 Issue 1). The `db_query_error`
        // below still surfaces the concrete failure to the operator.
        Err(err) => build_doctor_source_inventory_report(
            data_dir,
            false,
            Some(err.message),
            Vec::new(),
            detected_roots,
        ),
    }
}

fn doctor_source_inventory_deferred(reason: &str) -> DoctorSourceInventoryReport {
    DoctorSourceInventoryReport {
        schema_version: 1,
        db_available: false,
        db_query_error: Some(reason.to_string()),
        notes: vec![
            "Archive-wide source inventory was not attempted; zero-valued coverage fields are unknown, not evidence of absence."
                .to_string(),
        ],
        ..DoctorSourceInventoryReport::default()
    }
}

fn doctor_sources_config_path(data_dir: &Path) -> PathBuf {
    doctor_sources_config_path_from_config_result(
        data_dir,
        crate::sources::config::SourcesConfig::config_path(),
    )
}

fn doctor_sources_config_path_from_config_result(
    data_dir: &Path,
    config_path: Result<PathBuf, crate::sources::config::ConfigError>,
) -> PathBuf {
    config_path.unwrap_or_else(|_| data_dir.join("cass").join("sources.toml"))
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct DoctorSourcesConfigCheck {
    status: &'static str,
    message: String,
}

fn doctor_sources_config_check(sources_path: &Path) -> DoctorSourcesConfigCheck {
    if !sources_path.exists() {
        return DoctorSourcesConfigCheck {
            status: "pass",
            message: "No remote sources configured".to_string(),
        };
    }

    let content = match std::fs::read_to_string(sources_path) {
        Ok(content) => content,
        Err(e) => {
            return DoctorSourcesConfigCheck {
                status: "warn",
                message: format!("Cannot read sources config: {e}"),
            };
        }
    };

    match toml::from_str::<crate::sources::config::SourcesConfig>(&content) {
        Ok(config) => match config.validate() {
            Ok(()) => DoctorSourcesConfigCheck {
                status: "pass",
                message: "Sources config valid".to_string(),
            },
            Err(e) => DoctorSourcesConfigCheck {
                status: "warn",
                message: format!("Sources config validation warning: {e}"),
            },
        },
        Err(e) => DoctorSourcesConfigCheck {
            status: "warn",
            message: format!("Sources config parse error: {e}"),
        },
    }
}

const DOCTOR_RAW_MIRROR_ROOT_DIR: &str = "raw-mirror";
const DOCTOR_RAW_MIRROR_SCHEMA_VERSION: u32 = 1;
const DOCTOR_RAW_MIRROR_BACKFILL_GENERATION: u32 = 1;
const DOCTOR_RAW_MIRROR_VERSION_DIR: &str = "v1";
const DOCTOR_RAW_MIRROR_MANIFEST_KIND: &str = "cass_raw_session_mirror_v1";
const DOCTOR_RAW_MIRROR_HASH_ALGORITHM: &str = "blake3";
const DOCTOR_RAW_MIRROR_BLOB_EXTENSION: &str = "raw";
const DOCTOR_RAW_MIRROR_DIR_MODE: &str = "0700";
const DOCTOR_RAW_MIRROR_FILE_MODE: &str = "0600";
const CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY: &str = "CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY";
const CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY_MANIFEST_LIMIT: &str =
    "CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY_MANIFEST_LIMIT";
const CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY_BYTE_LIMIT: &str =
    "CASS_DOCTOR_RAW_MIRROR_FULL_VERIFY_BYTE_LIMIT";
const DOCTOR_RAW_MIRROR_DEFAULT_FULL_VERIFY_MANIFEST_LIMIT: usize = 256;
const DOCTOR_RAW_MIRROR_DEFAULT_FULL_VERIFY_BYTE_LIMIT: u64 = 512 * 1024 * 1024;
/// ub29t (gh#374 issue 4): `cass doctor check --json` emitted 17MB on a live
/// data dir, almost all of it per-manifest raw-mirror enumeration. By default
/// the `manifests` array now keeps every problem manifest plus at most this
/// many healthy ones; `--verbose` restores the full listing. Summary counts
/// are always computed over the complete set.
const DOCTOR_RAW_MIRROR_DEFAULT_LISTED_HEALTHY_MANIFESTS: usize = 64;

/// Keep every item flagged by `is_problem` (in original order) and at most
/// `healthy_cap` of the rest. Returns the kept items and how many healthy
/// items were omitted. Pure, so the elision policy is unit-testable without
/// building manifest reports.
fn doctor_bound_healthy_listing<T>(
    items: Vec<T>,
    healthy_cap: usize,
    is_problem: impl Fn(&T) -> bool,
) -> (Vec<T>, usize) {
    let mut kept = Vec::with_capacity(items.len().min(healthy_cap.saturating_add(16)));
    let mut healthy_kept = 0usize;
    let mut omitted = 0usize;
    for item in items {
        if is_problem(&item) {
            kept.push(item);
        } else if healthy_kept < healthy_cap {
            healthy_kept += 1;
            kept.push(item);
        } else {
            omitted += 1;
        }
    }
    (kept, omitted)
}

/// A manifest is a "problem" (never elided from the bounded listing) when it
/// is invalid, its blob is missing or mismatched, its manifest checksum
/// drifted, or its upstream source is gone. `manifest_unverified` (a legacy
/// manifest that never recorded a checksum) is a warning-class count, not a
/// per-manifest problem, and is elided like a healthy entry.
fn doctor_raw_mirror_manifest_is_problem(manifest: &DoctorRawMirrorManifestReport) -> bool {
    manifest.invalid_reason.is_some()
        || matches!(
            manifest.status.as_str(),
            "invalid_manifest" | "manifest_drift" | "checksum_mismatch" | "missing_blob"
        )
        || manifest.upstream_path_exists.is_some_and(|exists| !exists)
        || matches!(
            manifest.blob_checksum_status,
            DoctorArtifactChecksumStatus::Mismatched | DoctorArtifactChecksumStatus::Missing
        )
}

/// Apply the ub29t bounded listing to a doctor raw-mirror report in place.
/// `full` (from `--verbose`) keeps everything and only records the mode.
fn doctor_apply_raw_mirror_listing_bound(report: &mut DoctorRawMirrorReport, full: bool) {
    let total = report.manifests.len();
    if full {
        report.summary.listed_manifest_count = total;
        report.summary.omitted_healthy_manifest_count = 0;
        report.summary.listing_mode = "full";
        return;
    }
    let manifests = std::mem::take(&mut report.manifests);
    let (kept, omitted) = doctor_bound_healthy_listing(
        manifests,
        DOCTOR_RAW_MIRROR_DEFAULT_LISTED_HEALTHY_MANIFESTS,
        doctor_raw_mirror_manifest_is_problem,
    );
    report.summary.listed_manifest_count = kept.len();
    report.summary.omitted_healthy_manifest_count = omitted;
    report.summary.listing_mode = "bounded";
    report.manifests = kept;
    if omitted > 0 {
        report.notes.push(format!(
            "manifests listing is bounded: {} of {total} manifests shown ({omitted} healthy manifests elided; every problem manifest is retained). Re-run with --verbose for the full listing.",
            report.summary.listed_manifest_count
        ));
    }
}

#[cfg(test)]
mod doctor_raw_mirror_listing_bound_tests {
    use super::doctor_bound_healthy_listing;

    #[test]
    fn keeps_every_problem_and_caps_healthy_in_order() {
        // odd numbers are "problems"; cap healthy (even) at 2.
        let items: Vec<u32> = (1..=10).collect();
        let (kept, omitted) = doctor_bound_healthy_listing(items, 2, |n| !n.is_multiple_of(2));
        assert_eq!(kept, vec![1, 2, 3, 4, 5, 7, 9]);
        assert_eq!(omitted, 3);
    }

    #[test]
    fn small_sets_are_untouched_and_zero_cap_keeps_only_problems() {
        let (kept, omitted) =
            doctor_bound_healthy_listing(vec![2u32, 4], 64, |n| !n.is_multiple_of(2));
        assert_eq!(kept, vec![2, 4]);
        assert_eq!(omitted, 0);
        let (kept, omitted) =
            doctor_bound_healthy_listing(vec![1u32, 2, 4], 0, |n| !n.is_multiple_of(2));
        assert_eq!(kept, vec![1]);
        assert_eq!(omitted, 2);
    }
}

